UPDATE care_animal_plans cap JOIN ( SELECT t.animal_id, LOWER(TRIM(t.drug)) AS dcore, MIN(TRIM(t.dosage)) AS dos FROM treatments t WHERE TRIM(COALESCE(t.dosage, '')) <> '' AND TRIM(t.dosage) REGEXP '[[:alpha:]]' GROUP BY t.animal_id, LOWER(TRIM(t.drug)) HAVING COUNT(DISTINCT TRIM(t.dosage)) = 1 ) m ON m.animal_id = cap.animal_id SET cap.name = REPLACE(cap.name, CONCAT('Traitement — ', JSON_UNQUOTE(JSON_EXTRACT(cap.action_payload, '$.prompt'))), CONCAT('Traitement — ', JSON_UNQUOTE(JSON_EXTRACT(cap.action_payload, '$.prompt')), ' (', m.dos, ')')), cap.action_payload = JSON_SET(cap.action_payload, '$.prompt', CONCAT(JSON_UNQUOTE(JSON_EXTRACT(cap.action_payload, '$.prompt')), ' (', m.dos, ')')) WHERE cap.active = 1 AND cap.created_by IS NULL AND cap.action_kind = 'observation' AND cap.name LIKE 'Traitement — %' AND cap.action_payload IS NOT NULL AND JSON_VALID(cap.action_payload) AND JSON_EXTRACT(cap.action_payload, '$.prompt') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(cap.action_payload, '$.prompt')) = 'STRING' AND LOWER(TRIM(JSON_UNQUOTE(JSON_EXTRACT(cap.action_payload, '$.prompt')))) = m.dcore AND JSON_UNQUOTE(JSON_EXTRACT(cap.action_payload, '$.prompt')) NOT LIKE CONCAT('%(', m.dos, ')')
